package com.sora.splineroads.core;
import com.sora.splineroads.core.RoadGeometry.*;import java.util.*;
public class Interchange201Probe {
 static InterchangePlanner.Plan plan(boolean left,int lanes){var s=new Settings(Mode.STRAIGHT,Style.H4_RAIL,28,1,.4,90);var ns=new Node[]{new Node(new V(-600,4,0),-90,0),new Node(new V(600,4,0),-90,0),new Node(new V(0,25,-600),0,0),new Node(new V(0,25,600),0,0)};return InterchangePlanner.plan(ns,s,s,new InterchangePlanner.Options(InterchangePlanner.Preset.STACK,left,lanes,96,20,5,2));}
 public static void main(String[]args)throws Exception{var plan=plan(false,1);var all=plan.legs().stream().map(InterchangePlanner.Leg::mesh).toList();
 for(var leg:plan.legs()){var m=leg.mesh();double pos=0,neg=0;for(int i=1;i<m.samples().size();i++){var a=m.samples().get(i-1).left();var b=m.samples().get(i).left();double angle=Math.atan2(a.x()*b.z()-a.z()*b.x(),a.dot(b));if(angle>0)pos+=angle;else neg-=angle;}System.out.printf(java.util.Locale.ROOT,"leg=%s style=%s len=%.2f positive=%.4f negative=%.4f%n",leg.name(),m.settings().style(),m.length(),pos,neg);}
 var feed=plan.legs().stream().filter(l->l.name().equals("共用汇出 0")).findFirst().orElseThrow().mesh();for(double d=5;d<feed.length();d+=10){var at=RoadStructures.sample(feed,d);var q=RoadQueries.horizontal(all.get(0),at.center());System.out.println("FEED d="+d+" hostStation="+q.sample().distance()+" lateral="+q.lateral()+" hostHalf="+q.sample().halfWidth()+" rampHalf="+at.halfWidth()+" gap="+(Math.abs(q.lateral())-q.sample().halfWidth()-at.halfWidth()));}
 var method=RoadJunction.class.getDeclaredMethod("openGuide",Mesh.class,Sample.class,Sample.class,int.class,Mesh.class,Map.class,List.class);method.setAccessible(true);
 for(int index=0;index<2;index++){var main=all.get(index);var neighbors=all.stream().filter(m->m!=main).toList();int fits=0,open=0,painted=0;var paint=RoadJunction.markings(main,List.of(),neighbors,true);var cache=new IdentityHashMap<Mesh,RoadRailJoin>();
 for(double d=1;d<main.length()-1.5;d+=3)for(int side:new int[]{-1,1}){var a=RoadStructures.sample(main,d);var b=RoadStructures.sample(main,d+1.5);var mid=RoadStructures.sample(main,d+.75);for(var ramp:neighbors){if(!ramp.settings().style().ramp()||!LaneRampPaint.guideFits(main,a,b,side,ramp))continue;fits++;boolean value=(Boolean)method.invoke(null,main,a,b,side,ramp,cache,neighbors);if(value)open++;var point=mid.at(RoadProfile.layout(main,mid).outer(side),0);if(paint.stream().anyMatch(p->RoadSurface.area(RoadSurface.intersect(p.points(),List.of(point.add(new V(-.01,0,-.01)),point.add(new V(.01,0,-.01)),point.add(new V(.01,0,.01)),point.add(new V(-.01,0,.01)))))>1e-8))painted++;break;}}
 System.out.println("MAIN "+index+" guides fits="+fits+" open="+open+" painted="+painted);for(var ramp:neighbors)if(ramp.settings().style().ramp()){var range=RoadJunction.auxiliaryRange(ramp,main);if(range!=null)System.out.println("aux rampLen="+ramp.length()+" range="+Arrays.toString(range)+" width="+ramp.first().halfWidth()+" to "+ramp.last().halfWidth());}}
 }
}
